// db/init.js — Base de datos con catálogo COMPLETO de Hacienda PR (5,298 items)
// Fuente: CODIGOS_HACIENDA.XLS del SISCOMMATE
// Ejecutar: node db/init.js

const Database = require('better-sqlite3');
const path = require('path');
const DB_PATH = process.env.DB_PATH || path.join(__dirname, '../manifest.db');
console.log('Inicializando DB:', DB_PATH);
const db = new Database(DB_PATH);
db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');

// ─── TABLAS ────────────────────────────────────────────
db.exec(`
CREATE TABLE IF NOT EXISTS carriers (
  code TEXT PRIMARY KEY, scac TEXT, name TEXT, ss TEXT, ivu TEXT,
  dir1 TEXT, dir2 TEXT, dir3 TEXT, phones TEXT, sisurl TEXT, manifest TEXT);

CREATE TABLE IF NOT EXISTS ports (
  code TEXT PRIMARY KEY, description TEXT, country TEXT);

CREATE TABLE IF NOT EXISTS hacienda_items (
  code TEXT PRIMARY KEY, description TEXT NOT NULL,
  unit TEXT, tariff TEXT, taxable INTEGER DEFAULT 1);

CREATE TABLE IF NOT EXISTS clients (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT, ss TEXT, code TEXT, type TEXT, taxid TEXT,
  add1 TEXT, add2 TEXT, add3 TEXT, phone1 TEXT, phone2 TEXT, ivu TEXT);

CREATE TABLE IF NOT EXISTS manifests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  filename TEXT, voyage_no TEXT, vessel_code TEXT, vessel_name TEXT,
  biz_company_code TEXT, loading_port TEXT, unloading_port TEXT,
  departure_date TEXT, arrival_date TEXT, manifest_no TEXT,
  carrier_code TEXT, status TEXT DEFAULT 'borrador',
  created_at TEXT DEFAULT (datetime('now')), exported_at TEXT);

CREATE TABLE IF NOT EXISTS bills_of_lading (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  manifest_id INTEGER NOT NULL REFERENCES manifests(id) ON DELETE CASCADE,
  bl_no TEXT NOT NULL, bl_type TEXT, transit_type TEXT, unloading_port_code TEXT,
  goods_name TEXT, package_unit_code TEXT, package_qty INTEGER,
  gross_weight REAL, value REAL,
  consignor_type TEXT, consignor_code TEXT, consignor_name TEXT,
  consignor_document_type TEXT, consignor_document_no TEXT,
  consignor_country_code TEXT, consignor_tel TEXT, consignor_email TEXT,
  consignor_street TEXT, consignor_city TEXT, consignor_zip TEXT,
  consignee_type TEXT, consignee_code TEXT, consignee_name TEXT,
  consignee_document_type TEXT, consignee_document_no TEXT,
  consignee_country_code TEXT, consignee_tel TEXT, consignee_email TEXT,
  consignee_street TEXT, consignee_city TEXT, consignee_zip TEXT,
  notify_name TEXT, notify_code TEXT, notify_document_type TEXT,
  notify_document_no TEXT, notify_country_code TEXT, notify_tel TEXT,
  notify_email TEXT, notify_street TEXT, notify_city TEXT, notify_zip TEXT,
  hacienda_item_code TEXT, hacienda_tariff TEXT, hacienda_container_no TEXT,
  hacienda_client_ss TEXT, status TEXT DEFAULT 'pendiente',
  notes TEXT, modified_at TEXT DEFAULT (datetime('now')));

CREATE TABLE IF NOT EXISTS containers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  manifest_id INTEGER REFERENCES manifests(id) ON DELETE CASCADE,
  container_no TEXT, container_type TEXT, package_code TEXT,
  amount INTEGER, gross_weight REAL, net_weight REAL, seal_no1 TEXT);

CREATE TABLE IF NOT EXISTS container_bl (
  container_no TEXT, bl_no TEXT, manifest_id INTEGER);

CREATE TABLE IF NOT EXISTS export_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  manifest_id INTEGER REFERENCES manifests(id),
  exported_at TEXT DEFAULT (datetime('now')),
  filename TEXT, bl_count INTEGER, exported_by TEXT);
`);

